import { FIREBASE_CDN_BASE, initializeFirebaseServices } from "./firebase/firebaseApp.js";

const root = document.querySelector("#page-root");
const nav = document.querySelector(".topnav");
const ROUTES = new Set(["/actions","/people/master","/people-integrity","/employer/members","/system-health","/audit","/privacy-center"]);
const EMPLOYER = new Set(["verified_employer_member","org_admin","reviewer","admin","owner"]);
const ADMINS = new Set(["admin","owner"]);
const REVIEWERS = new Set(["reviewer","admin","owner"]);
const DEFAULT_PERMS = Object.freeze({runChecks:true,manageTalent:true,addEmploymentRecords:true,requestReports:true,manageMembers:false});
const RETENTION_DEFAULTS = Object.freeze({closedWorkflowDays:365,auditDays:730,inactiveAccountDays:365});
const PIPELINE = ["considering","interview","shortlist","offer","hired","passed","do_not_reconsider","archived"];

let auth, db, Auth, Fire, authUser, userDoc, ownMember;
let healthCache = null;
let mergePreview = null;
let privacySnapshot = null;
