function dupes(profiles){const buckets=new Map();for(const p of profiles.filter(x=>!x.mergedIntoProfileId&&lower(x.identityStatus)!=="merged")){for(const id of unique(p.discordIds||[],10)){const k=`discord-id:${id}`;if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(p);}for(const u of uniqueLower(p.discordUsernames||[p.discordUsername],10)){const k=`discord:${u}`;if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(p);}for(const u of uniqueLower(p.robloxUsernames||[p.robloxUsername],10)){const k=`roblox:${u}`;if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(p);}}const pairs=new Map();for(const[k,rows]of buckets){const u=[...new Map(rows.map(r=>[r.id,r])).values()];if(u.length<2)continue;for(let i=0;i<u.length;i++)for(let j=i+1;j<u.length;j++){const key=[u[i].id,u[j].id].sort().join("__");const e=pairs.get(key)||{a:u[i],b:u[j],signals:[]};e.signals.push(k);pairs.set(key,e);}}return[...pairs.values()].sort((a,b)=>b.signals.length-a.signals.length);}
async function relatedToSource(id){return Promise.all([q("employmentRecords","profileId","==",id).catch(()=>[]),q("reports","subjectProfileId","==",id).catch(()=>[]),q("screeningReportSummaries","subjectProfileId","==",id).catch(()=>[]),q("employerCandidates","profileId","==",id).catch(()=>[]),q("reportAccessRequests","subjectProfileId","==",id).catch(()=>[]),q("reportAccessGrants","subjectProfileId","==",id).catch(()=>[]),q("employmentRecordDisputes","profileId","==",id).catch(()=>[]),q("claims","profileId","==",id).catch(()=>[]),q("appeals","profileId","==",id).catch(()=>[]),q("checkLogs","targetProfileId","==",id).catch(()=>[])]);}
async function previewMerge(sourceRef,targetRef,reason){const[source,target]=await Promise.all([resolveProfile(sourceRef),resolveProfile(targetRef)]);if(!source||!target)throw new Error("Both source and target profiles must exist.");if(source.id===target.id)throw new Error("Source and target cannot be the same profile.");if(source.mergedIntoProfileId||lower(source.identityStatus)==="merged")throw new Error("The source is already merged.");if(source.linkedUserId&&source.linkedUserId!==target.linkedUserId)throw new Error("A separately linked account cannot be merged into a different linked profile. Keep the claimed account as the target or resolve identity ownership first.");const related=await relatedToSource(source.id);mergePreview={source,target,reason:clean(reason).slice(0,1000),related};return mergePreview;}
function previewHtml(s){const labels=["Employment","Reports","Summaries","Talent Lists","Access Requests","Access Grants","Disputes","Claims","Appeals","Checks"];const total=s.related.reduce((n,g)=>n+g.length,0);return`<div class="f19-card" style="margin-top:1rem"><div class="f19-section-head"><div><p class="eyebrow">Merge Preview</p><h3>${esc(s.source.displayName||s.source.cognitusId)} → ${esc(s.target.displayName||s.target.cognitusId)}</h3></div>${badge(`${total} references`,"warn")}</div><div class="f19-detail-grid">${labels.map((l,i)=>`<div class="f19-detail"><span>${esc(l)}</span><strong>${s.related[i].length}</strong></div>`).join("")}</div><div class="f19-notice warn" style="margin-top:1rem">Standing and Risk on the canonical target are not automatically overwritten.</div><button class="button button-dark" type="button" data-f19-merge-execute style="margin-top:1rem">Merge Into Canonical Profile</button></div>`;}
