async function integrityPage(){if(!owner()){root.innerHTML=`<main class="f19-shell">${shellHero("People Integrity","Owner access required.","Canonical merges are Owner-only because they move employment, report, access and candidate references.")}</main>`;return;}const profiles=await all("profiles").catch(()=>[]);const pairs=dupes(profiles);const preS=params().get("source")||"",preT=params().get("target")||"";root.innerHTML=`<main class="f19-shell">${shellHero("People Integrity","One person. One canonical record.","Detect likely duplicates, preview every reference move and preserve the old record as merge provenance.",`<span>Possible duplicate pairs</span><strong>${pairs.length}</strong><small>Discord IDs and normalized usernames</small>`)}<section class="f19-grid two"><article class="f19-section"><div class="f19-section-head"><div><p class="eyebrow">Merge Tool</p><h2>Preview a merge</h2></div></div><form class="f19-form" data-f19-merge-preview><label>Source profile<input name="source" value="${esc(preS)}" required placeholder="Profile ID or PRF-..."></label><label>Target canonical profile<input name="target" value="${esc(preT)}" required placeholder="Profile ID or PRF-..."></label><label>Reason<textarea name="reason" rows="4" maxlength="1000" required></textarea></label><button class="button button-dark" type="submit">Preview Merge</button></form><div data-f19-merge-preview-output></div></article><article class="f19-section"><h2>Guardrails</h2><div class="f19-list"><div class="f19-notice">The source remains as a merged historical profile pointing to the target.</div><div class="f19-notice">Employment, reports, summaries, access, claims, appeals, checks and Talent references are moved where supported.</div><div class="f19-notice warn">Standing and Risk stay with the canonical target and are never silently replaced.</div></div></article></section><section class="f19-section"><div class="f19-section-head"><div><p class="eyebrow">Detection</p><h2>Likely duplicate profiles</h2></div><span>${pairs.length} pairs</span></div>${pairs.length?`<div class="f19-list">${pairs.slice(0,80).map(p=>`<article class="f19-row"><div><strong>${esc(p.a.displayName||p.a.cognitusId)} ↔ ${esc(p.b.displayName||p.b.cognitusId)}</strong><span>${esc(p.a.cognitusId||p.a.id)} · ${esc(p.b.cognitusId||p.b.id)}</span><small>${esc(p.signals.join(", "))}</small></div><div class="f19-actions">${link(`#/people/master?profile=${encodeURIComponent(p.a.id)}`,"Record A")}${link(`#/people/master?profile=${encodeURIComponent(p.b.id)}`,"Record B")}${link(`#/people-integrity?source=${encodeURIComponent(p.b.id)}&target=${encodeURIComponent(p.a.id)}`,"Prepare Merge",true)}</div></article>`).join("")}</div>`:empty("No likely duplicates.","No exact identifier collision was detected.")}</section></main>`;}

