async function renderRoute(){const current=route();if(!ROUTES.has(current))return;const token=++routeToken;if(!authUser||!userDoc){root.innerHTML=`<main class="f19-shell">${shellHero("Login Required","Sign in to continue.","Foundation tools operate on authenticated Cognitus records.",link("#/login","Login",true))}</main>`;return;}if(!active()){root.innerHTML=`<main class="f19-shell">${shellHero("Account Restricted","This account is not active.",`Current status: ${human(userDoc.status)}.`)}</main>`;return;}try{if(current==="/actions")await actionPage();else if(current==="/people/master")await masterPage();else if(current==="/people-integrity")await integrityPage();else if(current==="/employer/members")await membersPage();else if(current==="/system-health")await healthPage();else if(current==="/audit")await auditPage();else if(current==="/privacy-center")await privacyPage();}catch(e){if(token!==routeToken||route()!==current)return;root.innerHTML=`<main class="f19-shell">${shellHero("Foundation Error","This workspace could not load.",e?.message||"Unknown Foundation error.")}<div class="f19-notice bad">${esc(e?.message||"Unknown error")}</div></main>`;}if(token===routeToken&&route()===current)root?.focus();}

async function onSubmit(e){const f=e.target;if(!(f instanceof HTMLFormElement))return;if(f.matches("[data-f19-merge-preview]")){e.preventDefault();const d=Object.fromEntries(new FormData(f).entries()),out=root.querySelector("[data-f19-merge-preview-output]");try{out.innerHTML=previewHtml(await previewMerge(d.source,d.target,d.reason));}catch(err){out.innerHTML=`<div class="f19-notice bad" style="margin-top:1rem">${esc(err?.message||"Preview failed.")}</div>`;}return;}if(f.matches("[data-f19-member-form]")){e.preventDefault();const b=f.querySelector('button[type="submit"]');if(b)b.disabled=true;try{await memberSave(f);await membersPage();await refreshActionCount();}catch(err){window.alert(err?.message||"Membership update failed.");if(b)b.disabled=false;}return;}if(f.matches("[data-f19-audit-form]")){e.preventDefault();const t=root.querySelector("[data-f19-audit-results]");if(t)t.innerHTML='<div class="f19-empty">Searching audit events…</div>';try{auditResults(await auditQuery(Object.fromEntries(new FormData(f).entries())));}catch(err){if(t)t.innerHTML=`<div class="f19-notice bad">${esc(err?.message||"Audit search failed.")}</div>`;}return;}if(f.matches("[data-f19-privacy-form]")){e.preventDefault();try{await privacyCreate(Object.fromEntries(new FormData(f).entries()));await privacyPage();await refreshActionCount();}catch(err){window.alert(err?.message||"Privacy request failed.");}return;}if(f.matches("[data-f19-retention-form]")){e.preventDefault();try{await retentionSave(Object.fromEntries(new FormData(f).entries()));await privacyPage();}catch(err){window.alert(err?.message||"Retention policy update failed.");}}}
async function onClick(e){const r=e.target.closest?.("[data-f19-repair]");if(r){r.disabled=true;try{await healthRepair(healthCache?.issues.find(i=>i.id===r.dataset.f19Repair));await healthPage();}catch(err){window.alert(err?.message||"Repair failed.");r.disabled=false;}return;}if(e.target.closest?.("[data-f19-rescan]")){healthCache=null;await healthPage();return;}if(e.target.closest?.("[data-f19-repair-all]")){const b=e.target.closest("[data-f19-repair-all]");b.disabled=true;try{const safe=(healthCache?.issues||[]).filter(i=>!["duplicate-profile","broken-user-org"].includes(i.type)).slice(0,100);for(const i of safe)await healthRepair(i);await audit("SYSTEM_HEALTH_REPAIR_BATCH","system","health",`Repaired ${safe.length} safe issues.`);await healthPage();}catch(err){window.alert(err?.message||"Safe repair batch stopped.");b.disabled=false;}return;}if(e.target.closest?.("[data-f19-merge-execute]")){if(!window.confirm("Merge the source profile into the canonical target?"))return;const b=e.target.closest("[data-f19-merge-execute]");b.disabled=true;try{const id=mergePreview?.target?.id;await mergeExecute();location.hash=`#/people/master?profile=${encodeURIComponent(id)}`;}catch(err){window.alert(err?.message||"Merge failed.");b.disabled=false;}return;}const rr=e.target.closest?.("[data-f19-remove-request]");if(rr){rr.disabled=true;try{await removalRequest(rr.dataset.f19RemoveRequest);await membersPage();await refreshActionCount();}catch(err){window.alert(err?.message||"Removal request failed.");rr.disabled=false;}return;}const rf=e.target.closest?.("[data-f19-remove-final]");if(rf){if(!window.confirm("Finalize removal from this organization?"))return;rf.disabled=true;try{await removalFinalize(rf.dataset.f19RemoveFinal);await membersPage();await refreshActionCount();}catch(err){window.alert(err?.message||"Removal failed.");rf.disabled=false;}return;}if(e.target.closest?.("[data-f19-data-export]")){exportData();return;}const pd=e.target.closest?.("[data-f19-privacy-decision]");if(pd){pd.disabled=true;const notes=root.querySelector(`[data-f19-privacy-notes="${CSS.escape(pd.dataset.id)}"]`)?.value||"";try{await privacyDecide(pd.dataset.id,pd.dataset.f19PrivacyDecision,notes);await privacyPage();await refreshActionCount();}catch(err){window.alert(err?.message||"Privacy decision failed.");pd.disabled=false;}}}

async function init(){mountStyles();const services=await initializeFirebaseServices();if(!services.ready)return;auth=services.auth;db=services.db;[Auth,Fire]=await Promise.all([import(`${FIREBASE_CDN_BASE}/firebase-auth.js`),import(`${FIREBASE_CDN_BASE}/firebase-firestore.js`)]);Auth.onAuthStateChanged(auth,async user=>{authUser=user;userDoc=user?await docGet("users",user.uid).catch(()=>null):null;ownMember=null;if(userDoc)await ensureOwnMember();navSync();await refreshActionCount();await renderRoute();});window.addEventListener("hashchange",async()=>{closeOps();navSync();await renderRoute();});window.addEventListener("pageshow",()=>{navSync();renderRoute();});nav?.addEventListener("click",e=>{const b=e.target.closest?.("[data-f19-ops-button]");if(b){e.preventDefault();e.stopPropagation();const o=b.closest("[data-f19-ops]");const open=!o.classList.contains("is-open");o.classList.toggle("is-open",open);b.setAttribute("aria-expanded",String(open));}else if(e.target.closest?.("a"))closeOps();});document.addEventListener("click",e=>{const o=nav?.querySelector("[data-f19-ops]");if(o&&!o.contains(e.target))closeOps();});root?.addEventListener("submit",onSubmit);root?.addEventListener("click",onClick);root?.addEventListener("change",e=>{if(e.target.matches?.("[data-f19-org-switch]"))location.hash=`#/employer/members?org=${encodeURIComponent(e.target.value)}`;});navSync();await renderRoute();}

init().catch(e=>console.warn("Cognitus Foundation V19 failed to initialize",e));
